#[derive(Default)]
struct RecordingLedger {
    balances: RefCell<HashMap<String, i64>>,
    journal: RefCell<Vec<Call>>,
}

impl Ledger for RecordingLedger {
    fn deposit(&self, id: &str, amount: i64) {
        *self.balances.borrow_mut().entry(id.to_owned()).or_default() += amount;
        self.journal.borrow_mut().push(Call::Deposit { id: id.to_owned(), amount });
    }
}
